// signerUsage displays the usage of the signer command and its subcommands.
func signerUsage() {
	fmt.Fprintln(os.Stderr, `Signer service makes digital signatures and proofs for verifiable credentials and presentations.`)
	fmt.Fprintf(os.Stderr, "Usage:\n    %s [globalflags] signer COMMAND [flags]\n\n", os.Args[0])
	fmt.Fprintln(os.Stderr, "COMMAND:")
	fmt.Fprintln(os.Stderr, `    namespaces: Namespaces returns all keys namespaces, which corresponds to enabled Vault transit engines.`)
	fmt.Fprintln(os.Stderr, `    namespace-keys: NamespaceKeys returns all keys in a given namespace.`)
	fmt.Fprintln(os.Stderr, `    verification-method: VerificationMethod returns a single public key formatted as DID verification method for a given namespace, key and did. When did:jwk is set for did, a did:jwk is generated from the key.`)
	fmt.Fprintln(os.Stderr, `    verification-methods: VerificationMethods returns all public keys in a given namespace. The result is formatted as array of DID verification methods with their controller attribute being the given DID in the request.`)
	fmt.Fprintln(os.Stderr, `    jwk-public-key: JwkPublicKey returns public key by name and namespace.`)
	fmt.Fprintln(os.Stderr, `    credential-proof: CredentialProof adds a proof to a given Verifiable Credential.`)
	fmt.Fprintln(os.Stderr, `    presentation-proof: PresentationProof adds a proof to a given Verifiable Presentation.`)
	fmt.Fprintln(os.Stderr, `    create-credential: CreateCredential creates VC with proof from raw JSON data.`)
	fmt.Fprintln(os.Stderr, `    create-presentation: CreatePresentation creates VP with proof from raw JSON data.`)
	fmt.Fprintln(os.Stderr, `    verify-credential: VerifyCredential verifies the proof of a Verifiable Credential.`)
	fmt.Fprintln(os.Stderr, `    verify-presentation: VerifyPresentation verifies the proof of a Verifiable Presentation.`)
	fmt.Fprintln(os.Stderr, `    sign: Sign creates digital signature on base64 encoded binary data.`)
	fmt.Fprintln(os.Stderr, `    did-doc: DidDoc implements didDoc.`)
	fmt.Fprintln(os.Stderr, `    did-list: DidList implements didList.`)
	fmt.Fprintln(os.Stderr, `    did-configuration: Creates did configuration.`)
	fmt.Fprintln(os.Stderr, `    jwks: Jwks implements Jwks.`)
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "Additional help:")
	fmt.Fprintf(os.Stderr, "    %s signer COMMAND --help\n", os.Args[0])
}
